SELECT AVG(pa.overall_rating) FROM main."Player_Attributes" pa WHERE CAST(pa."date" AS DATE) <= '2015-09-21' AND pa.id IN (SELECT pa2.id FROM main."Player_Attributes" pa2 INNER JOIN (SELECT player_api_id, MAX(CAST("date" AS DATE)) AS max_date FROM main."Player_Attributes" WHERE CAST("date" AS DATE) <= '2015-09-21' GROUP BY player_api_id) latest ON pa2.player_api_id = latest.player_api_id AND CAST(pa2."date" AS DATE) = latest.max_date);
